package com.intermarche.backoffice.engine.fieldops;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.stock.*;
import com.intermarche.backoffice.domain.shipping.*;
import com.intermarche.backoffice.domain.order.Product;
import com.intermarche.backoffice.domain.store.*;
import com.intermarche.backoffice.domain.executing.*;
import com.intermarche.backoffice.domain.wms.BaseHandlingOrder;
import com.intermarche.backoffice.domain.util.DateTimeProvider;
import com.intermarche.backoffice.engine.stock.StockQualityRules;
import com.intermarche.backoffice.engine.operator.OperatorFailure;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import jakarta.ws.rs.*;
import java.util.*;
import java.math.BigDecimal;
/** Safety decisions change eligibility, never inventory quantities. Each release is justified and appended. */
@ApplicationScoped @Transactional
public class QualityService {
 @Inject FieldOperationsService field;@Inject StockCommands receipts;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="QualityCaseInput") public static class Input {
  public Long storeId,productId,lotId,serialId;
  public String requestKey,expectedRevision,kind,reason;
  public Boolean includeUnknownLots;
 }
 private String revision(QualityCase c){return field.hash(Arrays.asList(c.id,c.version,c.state));}
 private Map<String,Object> summary(QualityCase c){var v=new LinkedHashMap<String,Object>();v.put("id",c.id);v.put("revision",revision(c));v.put("kind",c.kind);v.put("state",c.state);v.put("reason",c.reason);v.put("createdAt",c.createdAt);v.put("createdBy",c.createdBy);v.put("releasedBy",c.releasedBy);v.put("releaseReason",c.releaseReason);v.put("includeUnknownLots",c.includeUnknownLots);v.put("product",Map.of("id",id(c.product),"name",c.product.name,"ean",c.product.ean));v.put("lotId",c.lot==null?null:id(c.lot));v.put("lotCode",c.lot==null?null:c.lot.code);v.put("serialId",c.serial==null?null:id(c.serial));v.put("serialCode",c.serial==null?null:c.serial.code);return v;}
 private QualityCase required(Store store,Long caseId){QualityCase c=QualityCase.find("select c from QualityCase c join fetch c.product left join fetch c.lot left join fetch c.serial where c.store=?1 and c.id=?2",store,caseId).firstResult();if(c==null)throw new NotFoundException();return c;}
 public Object list(Long storeId,String state,Long productId,String query,long before,int limit){Store store=field.store(storeId,false);if(limit<1||limit>100||before<0||query!=null&&query.length()>120)throw new BadRequestException("Filtres qualité invalides");if(state!=null&&state.isBlank())state=null;if(state!=null&&!Set.of("ACTIVE","RELEASED").contains(state))throw new BadRequestException("État qualité inconnu");var args=new ArrayList<Object>();args.add(store);String where="c.store=?1";if(state!=null){args.add(state);where+=" and c.state=?"+args.size();}if(productId!=null){args.add(productId);where+=" and c.product.id=?"+args.size();}if(query!=null&&!query.isBlank()){args.add("%"+query.trim().toLowerCase(Locale.ROOT)+"%");int n=args.size();where+=" and (lower(c.product.name) like ?"+n+" or lower(c.reason) like ?"+n+")";}if(before>0){args.add(before);where+=" and c.id<?"+args.size();}var rows=QualityCase.<QualityCase>find("select c from QualityCase c join fetch c.product left join fetch c.lot left join fetch c.serial where "+where+" order by c.id desc",args.toArray()).range(0,limit).list();boolean more=rows.size()>limit;var page=rows.stream().limit(limit).toList();return Map.of("items",page.stream().map(this::summary).toList(),"hasMore",more,"nextBefore",page.isEmpty()?before:page.getLast().id);}
 public Object create(Input r){if(r==null||!Set.of("BLOCK","RECALL").contains(r.kind==null?"":r.kind))throw new BadRequestException("Blocage ou rappel requis");Store store=field.store(r.storeId,true);field.requireManager();FieldOperationsService.text(r.reason,2000);String fingerprint=field.hash(Arrays.asList("QUALITY_CREATE",r));var previous=receipts.previous(store,r.requestKey,fingerprint);if(previous!=null)return receipts.value(previous);
  Product product=Product.findById(r.productId);if(product==null)throw new NotFoundException("Produit inconnu");ManufacturerLot lot=r.lotId==null?null:ManufacturerLot.find("id=?1 and store=?2 and product=?3",r.lotId,store,product).firstResult();ProductSerial serial=r.serialId==null?null:ProductSerial.find("id=?1 and store=?2 and product=?3",r.serialId,store,product).firstResult();if(r.lotId!=null&&lot==null||r.serialId!=null&&serial==null)throw new BadRequestException("Lot ou série hors du magasin / produit");if(serial!=null&&lot!=null&&!Objects.equals(serial.lot==null?null:id(serial.lot),lot.id))throw new BadRequestException("Série d’un autre lot");if(lot==null&&serial!=null)lot=serial.lot;
  QualityCase c=new QualityCase();c.store=store;c.product=product;c.lot=lot;c.serial=serial;c.kind=r.kind;c.reason=r.reason.trim();c.createdBy=field.actor();c.includeUnknownLots=r.includeUnknownLots==null||r.includeUnknownLots;c.persistAndFlush();history(c,"CREATED",c.reason);dirty(store,product);notifyHolders(c);return receipts.record(store,r.requestKey,fingerprint,"QUALITY_CREATE",detail(store,c));
 }
 public Object release(Long caseId,Input r){if(r==null)throw new BadRequestException();Store store=field.store(r.storeId,true);field.requireManager();FieldOperationsService.text(r.reason,2000);String fingerprint=field.hash(Arrays.asList("QUALITY_RELEASE",caseId,r));var previous=receipts.previous(store,r.requestKey,fingerprint);if(previous!=null)return receipts.value(previous);QualityCase c=required(store,caseId);if(!Objects.equals(r.expectedRevision,revision(c)))throw new OperatorFailure(409,"STALE_QUALITY_CASE","Le dossier qualité a changé. Actualisez.");if(!"ACTIVE".equals(c.state))throw new BadRequestException("Ce dossier est déjà levé");c.state="RELEASED";c.releasedBy=field.actor();c.releaseReason=r.reason.trim();c.persistAndFlush();history(c,"RELEASED",c.releaseReason);dirty(store,c.product);field.notice(store,"quality-release:"+c.id+":"+r.requestKey,"Décision qualité levée",c.product.name+" · "+c.releaseReason,null,List.of(field.actor()));return receipts.record(store,r.requestKey,fingerprint,"QUALITY_RELEASE",detail(store,c));}
 private void dirty(Store store,Product product){StockAccount account=StockAccount.find("store=?1 and product=?2",store,product).firstResult();if(account!=null)account.alertDirty=true;}
 private void history(QualityCase c,String action,String reason){var event=new QualityCaseHistory();event.qualityCase=c;event.actor=field.actor();event.action=action;event.reason=reason;event.persist();}
 public Object read(Long storeId,Long caseId){Store store=field.store(storeId,false);return detail(store,required(store,caseId));}
 private Object detail(Store store,QualityCase c){var view=summary(c);view.put("canManage",field.manager());view.put("history",QualityCaseHistory.<QualityCaseHistory>list("qualityCase=?1 order by id",c).stream().map(h->Map.of("id",h.id,"actor",h.actor,"action",h.action,"reason",h.reason,"at",h.createdAt)).toList());view.put("trace",trace(store,id(c.product),c.lot==null?null:id(c.lot),c.serial==null?null:id(c.serial),c.includeUnknownLots));return view;}
 private void notifyHolders(QualityCase c){notifyParcelHolders(c);var picked=PickedItem.<PickedItem>list("select p from PickedItem p join fetch p.loadedTote t join fetch t.tote where t.tote.store=?1 and p.product=?2 and p.status=?3 and p.quantity>0 and not exists(select sl.id from ShipmentLine sl where sl.pickedItem=p)",c.store,c.product,PickedItem.PickStatus.PICKED);if(picked.isEmpty())return;var ids=picked.stream().map(p->p.id).toList();var known=new HashSet<Long>();for(var a:PickedStockAllocation.<PickedStockAllocation>list("select a from PickedStockAllocation a join fetch a.holding where a.state.store=?1 and a.state.itemId in ?2 and a.quantity>0",c.store,ids))if(StockQualityRules.matches(c,id(c.product),a.holding.lot==null?null:id(a.holding.lot),a.holding.serial==null?null:id(a.holding.serial)))known.add(a.state.itemId);
  var legacy=new HashSet<Long>();var tracked=new HashSet<Long>();for(var state:PickedStockState.<PickedStockState>list("store=?1 and itemId in ?2",c.store,ids)){tracked.add(state.itemId);if(state.legacyQuantity.signum()>0)legacy.add(state.itemId);}
  var affected=picked.stream().filter(p->known.contains(p.id)||c.lot==null&&c.serial==null||c.includeUnknownLots&&(legacy.contains(p.id)||!tracked.contains(p.id))).toList();if(affected.isEmpty())return;var toteIds=affected.stream().map(p->id(p.loadedTote)).distinct().toList();var owners=new LinkedHashMap<Long,String>();
  for(String entity:List.of("PickingExecution","GroupingExecution","DispositionExecution"))for(var row:PickedItem.getEntityManager().createQuery("select distinct e.handlingOrder.id,e.employee.badgeId from "+entity+" e join e.loadedTotes t where t.id in ?1 and e.handlingOrder.store=?2",Object[].class).setParameter(1,toteIds).setParameter(2,c.store).getResultList())owners.put((Long)row[0],(String)row[1]);
  for(var owner:owners.entrySet()){var report=new FieldOperationsService.Report();report.storeId=id(c.store);report.orderId=owner.getKey();report.productId=id(c.product);report.requestKey="quality-"+c.id+"-"+owner.getKey();report.kind="SAFETY";report.title=("RECALL".equals(c.kind)?"Rappel":"Blocage")+" · "+c.product.name;report.title=report.title.substring(0,Math.min(120,report.title.length()));report.comment=c.reason;report.observedAddress="Supports concernés : "+affected.stream().map(p->p.loadedTote.tote.code).distinct().reduce((a,b)->a+", "+b).orElse("");if(report.observedAddress.length()>300)report.observedAddress=report.observedAddress.substring(0,297)+"…";field.report(report);field.notice(c.store,"quality:"+c.id+":"+owner.getKey(),report.title,c.reason+" · Traitez les produits dans la tuile Qualité.",owner.getKey(),List.of(owner.getValue()));}
 }
 public void notifySegment(StockSegment segment,String reason,String requestKey){
  var rows=PickedItem.getEntityManager().createQuery("select distinct p.loadedTote.id,p.loadedTote.tote.code from PickedStockAllocation a join PickedItem p on p.id=a.state.itemId where a.holding=?1 and a.shipped=false and a.quantity>0 and p.status=?2",Object[].class).setParameter(1,segment).setParameter(2,PickedItem.PickStatus.PICKED).getResultList();if(rows.isEmpty())return;
  var toteIds=rows.stream().map(r->(Long)r[0]).toList();String codes=rows.stream().map(r->r[1].toString()).distinct().reduce((a,b)->a+", "+b).orElse("");var owners=new LinkedHashMap<Long,String>();
  for(String entity:List.of("PickingExecution","GroupingExecution","DispositionExecution"))for(var row:PickedItem.getEntityManager().createQuery("select distinct e.handlingOrder.id,e.employee.badgeId from "+entity+" e join e.loadedTotes t where t.id in ?1 and e.handlingOrder.store=?2",Object[].class).setParameter(1,toteIds).setParameter(2,segment.account.store).getResultList())owners.put((Long)row[0],(String)row[1]);
  for(var owner:owners.entrySet()){var report=new FieldOperationsService.Report();report.storeId=id(segment.account.store);report.orderId=owner.getKey();report.productId=id(segment.account.product);report.kind="SAFETY";report.title="Stock "+segment.quality+" · "+segment.account.product.name;report.title=report.title.substring(0,Math.min(120,report.title.length()));report.comment=reason;report.requestKey="segment-"+segment.id+"-"+com.intermarche.backoffice.engine.stock.StockTraceLedger.key(requestKey,owner.getKey()).substring(0,20);report.observedAddress="Supports : "+codes;report.observedAddress=report.observedAddress.substring(0,Math.min(300,report.observedAddress.length()));field.report(report);field.notice(segment.account.store,report.requestKey,report.title,reason,owner.getKey(),List.of(owner.getValue()));}
 }
 private void notifyParcelHolders(QualityCase c){var contents=ParcelContent.<ParcelContent>list("select pc from ParcelContent pc join fetch pc.parcel p where p.store=?1 and p.materialized=true and p.state<>'DISPATCHED' and pc.pickedItem.product=?2",c.store,c.product);if(contents.isEmpty())return;var ids=contents.stream().map(pc->id(pc.pickedItem)).toList();var affected=new HashSet<Long>();for(var a:PickedStockAllocation.<PickedStockAllocation>list("select a from PickedStockAllocation a join fetch a.holding where a.state.itemId in ?1 and a.shipped=false and a.quantity>0",ids))if(StockQualityRules.matches(c,id(c.product),a.holding.lot==null?null:id(a.holding.lot),a.holding.serial==null?null:id(a.holding.serial)))affected.add(a.state.itemId);var parcels=contents.stream().filter(pc->affected.contains(id(pc.pickedItem))).map(pc->pc.parcel).distinct().toList();var owners=new HashMap<Long,List<String>>();if(!parcels.isEmpty())for(Object[] row:PickedItem.getEntityManager().createQuery("select u.parcel.id,u.departure.owner.badgeId from DepartureUnit u where u.parcel in ?1 and u.state='LOADED'",Object[].class).setParameter(1,parcels).getResultList())owners.computeIfAbsent((Long)row[0],ignored->new ArrayList<>()).add((String)row[1]);for(var p:parcels){var audience=new TreeSet<>(owners.getOrDefault(p.id,List.of()));if(p.createdBy!=null)audience.add(p.createdBy);field.notice(c.store,"quality-parcel:"+c.id+":"+p.id,p.code+" · blocage qualité",c.reason+" · Déchargez et isolez le colis. Dossier qualité #"+c.id,null,audience);}}
 public Object traceSerial(Long storeId,Long productId,Long lotId,String code){Store store=field.store(storeId,false);FieldOperationsService.text(code,100);ProductSerial serial=ProductSerial.find("store=?1 and product.id=?2 and code=?3",store,productId,code.trim()).firstResult();if(serial==null)return Map.of("positions",List.of(),"goods",List.of(),"legacyNotice","Aucune série correspondante dans ce magasin et ce produit.");return trace(store,productId,lotId,serial.id,false);}
 public Object trace(Long storeId,Long productId,Long lotId,Long serialId){return trace(field.store(storeId,false),productId,lotId,serialId,false);}
 private Object trace(Store store,Long productId,Long lotId,Long serialId,boolean includeUnknown){
  // Scalar projections keep product / location graphs out of the trace screen.
  var args=new ArrayList<Object>(List.of(store,productId,DateTimeProvider.now()));String where="s.account.store=?1 and s.account.product.id=?2";
  if(lotId!=null){args.add(lotId);where+=" and (s.lot.id=?"+args.size()+(includeUnknown?" or s.lot is null":"")+")";}if(serialId!=null){args.add(serialId);where+=" and (s.serial.id=?"+args.size()+(includeUnknown?" or s.serial is null":"")+")";}
  var q=StockSegment.getEntityManager().createQuery("select s.id,s.location.locationCode,s.support.code,s.lot.code,s.serial.code,s.quality,s.lot.useBy,s.lot.bestBefore,sum(m.quantity) from StockSegment s left join s.support left join s.lot left join s.serial join StockMovement m on m.segment=s and m.effectiveAt<=?3 where "+where+" group by s.id,s.location.locationCode,s.support.code,s.lot.code,s.serial.code,s.quality,s.lot.useBy,s.lot.bestBefore having sum(m.quantity)<>0 order by s.id",Object[].class);for(int n=0;n<args.size();n++)q.setParameter(n+1,args.get(n));
  var positions=q.setMaxResults(500).getResultList().stream().map(r->{var v=new LinkedHashMap<String,Object>();String[] names={"segmentId","address","supportCode","lotCode","serialCode","quality","useBy","bestBefore","quantity"};for(int n=0;n<names.length;n++)v.put(names[n],r[n]);return v;}).toList();
  var allocations=PickedStockAllocation.<PickedStockAllocation>find("select a from PickedStockAllocation a join fetch a.state st join fetch a.holding h left join fetch h.lot left join fetch h.serial where st.store=?1 and st.product.id=?2 and a.quantity>0 order by a.id desc",store,productId).range(0,499).list();var goods=new ArrayList<Map<String,Object>>();
  var itemIds=allocations.stream().map(a->a.state.itemId).toList();var actual=new HashMap<Long,PickedItem>();if(!itemIds.isEmpty())for(var item:PickedItem.<PickedItem>list("select p from PickedItem p left join fetch p.loadedTote t left join fetch t.tote left join fetch t.buffer left join fetch t.cabinet where p.id in ?1",itemIds))actual.put(item.id,item);
  for(var a:allocations){if(lotId!=null&&!Objects.equals(a.holding.lot==null?null:id(a.holding.lot),lotId)&&!(includeUnknown&&a.holding.lot==null))continue;if(serialId!=null&&!Objects.equals(a.holding.serial==null?null:id(a.holding.serial),serialId)&&!(includeUnknown&&a.holding.serial==null))continue;var item=actual.get(a.state.itemId);var row=new LinkedHashMap<String,Object>();row.put("itemId",a.state.itemId);row.put("lotLineId",a.state.lotLineId);row.put("quantity",a.quantity);row.put("lotCode",a.holding.lot==null?null:a.holding.lot.code);row.put("serialCode",a.holding.serial==null?null:a.holding.serial.code);row.put("state",a.shipped?"SHIPPED":item==null?"HISTORICAL":"IN_TOTE");row.put("toteCode",item==null||item.loadedTote==null?null:item.loadedTote.tote.code);row.put("bufferCode",item==null||item.loadedTote==null||item.loadedTote.buffer==null?null:item.loadedTote.buffer.bufferCode);row.put("cabinetCode",item==null||item.loadedTote==null||item.loadedTote.cabinet==null?null:item.loadedTote.cabinet.code);row.put("cellRow",item==null||item.loadedTote==null?null:item.loadedTote.cellRow);row.put("cellColumn",item==null||item.loadedTote==null?null:item.loadedTote.cellColumn);goods.add(row);}
  if(includeUnknown||lotId==null&&serialId==null)for(var state:PickedStockState.<PickedStockState>find("select st from PickedStockState st left join fetch st.legacyTote t left join fetch t.tote left join fetch t.buffer left join fetch t.cabinet where st.store=?1 and st.product.id=?2 and st.legacyQuantity>0 order by st.id",store,productId).range(0,499).list()){
   var row=new LinkedHashMap<String,Object>();row.put("itemId",state.itemId);row.put("lotLineId",state.lotLineId);row.put("quantity",state.legacyQuantity);row.put("state","LEGACY_SOURCE_UNKNOWN");row.put("lotCode",null);row.put("serialCode",null);row.put("toteCode",state.legacyTote==null?null:state.legacyTote.tote.code);row.put("bufferCode",state.legacyTote==null||state.legacyTote.buffer==null?null:state.legacyTote.buffer.bufferCode);row.put("cabinetCode",state.legacyTote==null||state.legacyTote.cabinet==null?null:state.legacyTote.cabinet.code);row.put("cellRow",state.legacyTote==null?null:state.legacyTote.cellRow);row.put("cellColumn",state.legacyTote==null?null:state.legacyTote.cellColumn);goods.add(row);
  }
  var lines=goods.stream().map(row->(Long)row.get("lotLineId")).filter(Objects::nonNull).distinct().toList();var customers=new HashMap<Long,List<Map<String,Object>>>();
  if(!lines.isEmpty())for(var row:PickedItem.getEntityManager().createQuery("select distinct ll.id,c.fulfillment.order.id,c.fulfillment.order.orderId from FulfillmentChunk c join c.lines fl join LotLine ll on ll.fulfillmentLine=fl where ll.id in ?1 and c.fulfillment.order.store=?2",Object[].class).setParameter(1,lines).setParameter(2,store).getResultList())customers.computeIfAbsent((Long)row[0],unused->new ArrayList<>()).add(Map.of("id",row[1],"code",row[2]));
  if(!lines.isEmpty())for(var row:PickedItem.getEntityManager().createQuery("select distinct ll.id,l.fulfillment.order.id,l.fulfillment.order.orderId from Lot l join l.lines ll where ll.id in ?1 and l.fulfillment.order.store=?2",Object[].class).setParameter(1,lines).setParameter(2,store).getResultList()){var list=customers.computeIfAbsent((Long)row[0],unused->new ArrayList<>());if(list.stream().noneMatch(v->Objects.equals(v.get("id"),row[1])))list.add(Map.of("id",row[1],"code",row[2]));}
  var goodsIds=goods.stream().map(row->(Long)row.get("itemId")).distinct().toList();var parcelByItem=new HashMap<Long,Parcel>();if(!goodsIds.isEmpty())for(var pc:ParcelContent.<ParcelContent>list("select pc from ParcelContent pc join fetch pc.parcel p left join fetch p.currentBuffer where p.store=?1 and p.materialized=true and pc.pickedItem.id in ?2",store,goodsIds))parcelByItem.put(id(pc.pickedItem),pc.parcel);for(var row:goods){var p=parcelByItem.get((Long)row.get("itemId"));if(p!=null){row.put("parcelId",p.id);row.put("parcelCode",p.code);row.put("parcelAddress",p.currentAddress);if(!"SHIPPED".equals(row.get("state")))row.put("state","LOADED".equals(p.state)?"LOADED":"IN_PARCEL");row.put("bufferCode",p.currentBuffer==null?null:p.currentBuffer.bufferCode);}}var shipments=new HashMap<Long,List<Map<String,Object>>>();
  if(!goodsIds.isEmpty())for(var row:PickedItem.getEntityManager().createQuery("select sl.pickedItem.id,sh.id,sh.code,sh.dispatchedAt,sh.mode,sl.quantity,sl.departureBuffer from Shipment sh join sh.lines sl where sh.store=?1 and sl.pickedItem.id in ?2 order by sh.dispatchedAt",Object[].class).setParameter(1,store).setParameter(2,goodsIds).getResultList()){var v=new LinkedHashMap<String,Object>();String[] names={"itemId","id","code","dispatchedAt","mode","quantity","departureBuffer"};for(int n=1;n<names.length;n++)v.put(names[n],row[n]);shipments.computeIfAbsent((Long)row[0],unused->new ArrayList<>()).add(v);}
  for(var row:goods){row.put("customerOrders",customers.getOrDefault((Long)row.get("lotLineId"),List.of()));row.put("shipments",shipments.getOrDefault((Long)row.get("itemId"),List.of()));}
  var movementQuery=StockMovement.getEntityManager().createQuery("select m.id,m.effectiveAt,m.quantity,m.reason,m.eventKey,s.location.locationCode,s.support.code,s.lot.code,s.serial.code from StockMovement m join m.segment s left join s.support left join s.lot left join s.serial where "+where+" and m.effectiveAt<=?3 order by m.effectiveAt desc,m.id desc",Object[].class);for(int n=0;n<args.size();n++)movementQuery.setParameter(n+1,args.get(n));
  var movements=movementQuery.setMaxResults(300).getResultList().stream().map(r->{Map<String,Object> v=new LinkedHashMap<>();String[] names={"id","at","quantity","reason","eventKey","address","supportCode","lotCode","serialCode"};for(int n=0;n<names.length;n++)v.put(names[n],r[n]);return v;}).toList();
  return Map.of("positions",positions,"goods",goods,"movements",movements,"limited",positions.size()==500||goods.size()>=500||movements.size()==300,"legacyNotice","Les prélèvements historiques sans lot ne sont pas attribués artificiellement à un lot fabricant.");
 }
}
